mapper.select:
SELECT COUNT(*)
FROM travel_goal
WHERE del_yn = 'N'
  AND user_id = #{userId}
  AND status = #{status}

mapper.update:
UPDATE travel_goal
SET places = CAST(#{places} AS JSON),
    modified_date = NOW(),
    modified_nm = #{modifiedNm}
WHERE goal_id = #{goalId}
  AND del_yn = 'N'

UPDATE travel_goal
SET benefits = CAST(#{products} AS JSON),
    modified_date = NOW(),
    modified_nm = #{modifiedNm}
WHERE goal_id = #{goalId}
  AND user_id = #{userId}
  AND status = 'DRAFT'
  AND del_yn = 'N'

UPDATE travel_goal
SET status = 'CONFIRMED',
    modified_date = NOW(),
    modified_nm = #{modifiedNm}
WHERE goal_id = #{goalId}
  AND user_id = #{userId}
  AND status = 'DRAFT'
  AND del_yn = 'N'
